import UIKit
import Capacitor
import AuthenticationServices

// 아가미파이터 1.1.11 계정 연동: Apple로 로그인 → identityToken만 웹 쪽에 넘긴다(이름·이메일은 요청하지 않음)
@objc(GfAppleSignInPlugin)
public class GfAppleSignInPlugin: CAPPlugin, CAPBridgedPlugin, ASAuthorizationControllerDelegate, ASAuthorizationControllerPresentationContextProviding {
    public let identifier = "GfAppleSignInPlugin"
    public let jsName = "SignInWithApple"
    public let pluginMethods: [CAPPluginMethod] = [
        CAPPluginMethod(name: "authorize", returnType: CAPPluginReturnPromise)
    ]
    private var pending: CAPPluginCall?

    @objc func authorize(_ call: CAPPluginCall) {
        DispatchQueue.main.async {
            let req = ASAuthorizationAppleIDProvider().createRequest()
            req.requestedScopes = []
            if let n = call.getString("nonce") { req.nonce = n }
            if let s = call.getString("state") { req.state = s }
            self.pending = call
            let c = ASAuthorizationController(authorizationRequests: [req])
            c.delegate = self
            c.presentationContextProvider = self
            c.performRequests()
        }
    }

    public func presentationAnchor(for controller: ASAuthorizationController) -> ASPresentationAnchor {
        return self.bridge?.webView?.window ?? UIWindow()
    }

    public func authorizationController(controller: ASAuthorizationController, didCompleteWithAuthorization authorization: ASAuthorization) {
        guard let call = pending else { return }
        pending = nil
        guard let cred = authorization.credential as? ASAuthorizationAppleIDCredential,
              let data = cred.identityToken,
              let tok = String(data: data, encoding: .utf8) else {
            call.reject("no token")
            return
        }
        call.resolve(["response": ["user": cred.user, "identityToken": tok]])
    }

    public func authorizationController(controller: ASAuthorizationController, didCompleteWithError error: Error) {
        guard let call = pending else { return }
        pending = nil
        call.reject(error.localizedDescription)
    }
}

